/** Costo unitario promedio histórico. 0 si el producto nunca se ha vendido. */
export function costoUnitario(codigo: string, empresa = "sumigases"): number {
  return TABLA[empresa]?.[codigo.trim()]?.c ?? 0;
}
/** Precio unitario promedio histórico (referencia para cargar renglones). */
export function precioUnitario(codigo: string, empresa = "sumigases"): number {
  return TABLA[empresa]?.[codigo.trim()]?.p ?? 0;
}
export function tieneCosto(codigo: string, empresa = "sumigases"): boolean {
  return (TABLA[empresa]?.[codigo.trim()]?.c ?? 0) > 0;
}
